from scipy.spatial import distance


def total_travel_distance(points):
    """
    Calculate the total travel distance of a round-trip path.

    The path starts at the first point, visits each consecutive point,
    and returns to the starting point. Points may be given as 2-tuples
    or as single numbers (in which case both coordinates are assumed
    equal to that number). Returns 0.0 for an empty list or a list
    containing only one point.
    """
    # Normalize: empty list or a single point -> zero distance.
    if not points or len(points) == 1:
        return 0.0

    # Convert each point to a proper (x, y) pair.
    # A tuple/list with a single number means both coordinates equal it;
    # zip_longest pairs coordinates with a fill value equal to the item itself.
    coords = []
    for point in points:
        if isinstance(point, (tuple, list)):
            if len(point) == 1:
                coords.append((float(point[0]), float(point[0])))
            else:
                coords.append((float(point[0]), float(point[1])))
        else:
            # A bare number: both coordinates equal it.
            coords.append((float(point), float(point)))

    total = 0.0
    n = len(coords)
    for i in range(n):
        current = coords[i]
        nxt = coords[(i + 1) % n]  # wraps around back to the first point
        total += distance.euclidean(current, nxt)
    return total
